input.new_string:
function normUrl(u){ return u.replace(/\/+$/,"").toLowerCase(); }
function showSaveMsg(kind, text){
  var m=document.getElementById("savemsg");
  m.className="savemsg "+kind; m.textContent=text;
  if(kind) setTimeout(function(){ if(m.textContent===text){ m.className="savemsg"; m.textContent=""; } }, 4000);
}

document.getElementById("saver").addEventListener("submit", function(e){
  e.preventDefault();
  var urlEl=document.getElementById("url"); var raw=urlEl.value.trim();
  if(!raw){ showSaveMsg("err","Please paste a link first."); return; }
  var url=raw; if(!/^https?:\/\//i.test(url)) url="https://"+url;
  // plausible web address? needs a dot and a domain-looking host
  var host=hostOf(url);
  if(!/^[^\s]+\.[^\s]{2,}$/.test(host)){ showSaveMsg("err","That doesn't look like a web address. Check the link and try again."); return; }
  var items=load();
  // duplicate?
  var existing=null;
  for(var k=0;k<items.length;k++){ if(normUrl(items[k].url)===normUrl(url)){ existing=items[k]; break; } }
  if(existing){
    showSaveMsg("dup","You've already saved this link — jumping to it below.");
    urlEl.value="";
    state.q=""; state.tagFilters=[]; state.view="all";
    document.getElementById("search").value="";
    render();
    var el=document.querySelector('[data-id="'+existing.id+'"]');
    if(el){ el.classList.add("flash"); el.scrollIntoView({behavior:"smooth",block:"center"}); }
    return;
  }
  var id="n"+Date.now();
  items.push({ id:id, url:url, host:host, title:"", desc:"", tags:[], note:"", inList:false, loading:true, savedAt:Date.now() });
  persist(items); urlEl.value=""; urlEl.focus(); render();

