var sec=document.createElement("p"); sec.className="secondary";
sec.textContent=host+(item.loading?"":" · Saved "+fmtDate(item.savedAt));
body.appendChild(sec);

if(!item.loading){
  var rr=document.createElement("div"); rr.className="removerow";
  if(confirmingDelete[item.id]){
    var cd=document.createElement("span"); cd.className="confirmdel";
    cd.appendChild(document.createTextNode("Remove this link for good?"));
    var yes=document.createElement("button"); yes.className="yes"; yes.textContent="Remove";
    yes.onclick=function(){ var arr=load().filter(function(x){return x.id!==item.id;}); delete confirmingDelete[item.id]; persist(arr); render(); };
    var no=document.createElement("button"); no.textContent="Cancel";
    no.onclick=function(){ delete confirmingDelete[item.id]; render(); };
    cd.appendChild(yes); cd.appendChild(no); rr.appendChild(cd);
  } else {
    var rl=document.createElement("button"); rl.className="removelink"; rl.textContent="Remove";
    rl.onclick=function(){ confirmingDelete[item.id]=true; render(); };
    rr.appendChild(rl);
  }
  body.appendChild(rr);
}

li.appendChild(body); list.appendChild(li);

