:root {
  --bg:#f6f7f9; --card:#fff; --ink:#1f2430; --muted:#6b7280; --faint:#9aa1ac;
  --line:#e5e7eb; --accent:#2f6feb; --chip:#eef2ff; --chip-ink:#3949ab;
  --warn-bg:#fff3e0; --warn-ink:#b26a00; --danger:#c0392b;
}
* { box-sizing: border-box; }
body { margin:0; font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif; background:var(--bg); color:var(--ink); }
.wrap { max-width:720px; margin:0 auto; padding:0 16px; }
header { background:var(--card); border-bottom:1px solid var(--line); padding:18px 0; }
header h1 { margin:0; font-size:18px; }
header p { margin:4px 0 0; color:var(--muted); font-size:13px; }
main { padding:20px 16px 64px; }

.saver { background:var(--card); border:1px solid var(--line); border-radius:12px; padding:14px; margin-bottom:16px; }
.saver label { display:block; font-size:12px; color:var(--muted); margin:0 0 4px; }
.row { display:flex; gap:8px; }
.row input { flex:1; padding:10px 12px; border:1px solid var(--line); border-radius:8px; font-size:14px; }
button.primary { padding:10px 16px; background:var(--accent); color:#fff; border:none; border-radius:8px; font-size:14px; font-weight:600; cursor:pointer; white-space:nowrap; }
button.primary:hover { filter:brightness(.95); }
button.primary:disabled { opacity:.6; cursor:default; }
.hint { font-size:12px; color:var(--faint); margin:8px 0 0; }
.savemsg { font-size:13px; margin:8px 0 0; display:none; }
.savemsg.err { display:block; color:var(--danger); }
.savemsg.dup { display:block; color:var(--warn-ink); }

.toolbar { position:sticky; top:0; background:var(--bg); padding:8px 0 4px; z-index:5; }
.searchbox { position:relative; }
.searchbox input { width:100%; padding:10px 34px; border:1px solid var(--line); border-radius:10px; font-size:14px; background:#fff; }
.searchbox .mag { position:absolute; left:11px; top:50%; transform:translateY(-50%); color:var(--faint); font-size:14px; }
.searchbox .clr { position:absolute; right:8px; top:50%; transform:translateY(-50%); border:none; background:none; color:var(--faint); cursor:pointer; font-size:16px; display:none; }
.views { display:flex; gap:6px; margin:12px 0 6px; }
.views button { font-size:13px; padding:6px 14px; border:1px solid var(--line); background:#fff; border-radius:999px; color:var(--muted); cursor:pointer; }
.views button.on { background:var(--accent); color:#fff; border-color:var(--accent); }
.filters { display:flex; flex-wrap:wrap; gap:6px; align-items:center; }
.filters .lbl { font-size:12px; color:var(--faint); }
.filters .fchip { font-size:12px; padding:3px 8px; border-radius:999px; background:var(--accent); color:#fff; display:inline-flex; gap:6px; align-items:center; cursor:pointer; }
.filters .clearall { font-size:12px; color:var(--accent); background:none; border:none; cursor:pointer; }

.count { font-size:13px; color:var(--muted); margin:12px 0; }

ul.links { list-style:none; margin:0; padding:0; display:grid; gap:10px; }
li.link { background:var(--card); border:1px solid var(--line); border-radius:12px; padding:14px 16px; display:flex; gap:12px; }
li.link.flash { animation: flash 1.4s ease; }
@keyframes flash { 0%,100%{ background:var(--card);} 25%{ background:#fff6d6;} }
.favicon { flex:0 0 auto; width:36px; height:36px; border-radius:8px; display:flex; align-items:center; justify-content:center; color:#fff; font-weight:700; font-size:16px; }
.favicon.blank { background:#c3c8d0 !important; }
.body { flex:1; min-width:0; }
.toprow { display:flex; align-items:flex-start; gap:10px; }
.maintext { flex:1; min-width:0; }
.title { font-size:15px; font-weight:600; margin:0 0 3px; }
.title a { color:var(--ink); text-decoration:none; }
.title a:hover { text-decoration:underline; }
.title.loading { color:var(--faint); font-weight:500; }
.warn { font-size:12px; color:var(--warn-ink); background:var(--warn-bg); border-radius:6px; padding:4px 9px; display:inline-flex; align-items:center; gap:6px; margin:0 0 8px; }
.desc { font-size:13px; color:var(--muted); margin:0 0 8px; line-height:1.4; }
.linkfield { display:flex; gap:6px; margin:0 0 8px; }
.linkfield input { flex:1; padding:7px 9px; border:1px solid var(--line); border-radius:6px; font-size:14px; }
.miniadd { font-size:12px; color:var(--muted); background:none; border:none; cursor:pointer; padding:0; margin:0 0 8px; }
.miniadd:hover { color:var(--accent); }

.tagrow { display:flex; flex-wrap:wrap; gap:6px; align-items:center; margin:0 0 8px; }
.tag { font-size:12px; padding:2px 8px; border-radius:999px; background:var(--chip); color:var(--chip-ink); display:inline-flex; align-items:center; gap:5px; cursor:pointer; }
.tag.active { outline:2px solid var(--accent); }
.tag .x { border:none; background:none; color:var(--chip-ink); cursor:pointer; font-size:13px; line-height:1; padding:0; opacity:.55; }
.tag .x:hover { opacity:1; }
.taginput { border:1px solid var(--line); border-radius:8px; padding:5px 8px; font-size:13px; min-width:110px; }

.note { font-size:13px; color:#4b5563; background:#fbfbf4; border:1px solid #f0efe0; border-left:3px solid #e3c766; border-radius:6px; padding:6px 9px; margin:0 0 8px; line-height:1.4; white-space:pre-wrap; cursor:text; }
.noteedit { margin:0 0 8px; }
.noteedit textarea { width:100%; border:1px solid var(--line); border-radius:6px; padding:7px 9px; font:inherit; font-size:13px; resize:vertical; min-height:52px; }
.nbtns { display:flex; gap:6px; margin-top:6px; }

.statepill { font-size:11px; padding:2px 8px; border-radius:999px; white-space:nowrap; }
.statepill.inlist { background:var(--warn-bg); color:var(--warn-ink); }
.act { font-size:12px; padding:5px 10px; border-radius:8px; border:1px solid var(--line); background:#fff; cursor:pointer; white-space:nowrap; }
.act:hover { border-color:var(--accent); color:var(--accent); }
.act.primary { background:var(--accent); color:#fff; border-color:var(--accent); }
.act.primary:hover { filter:brightness(.95); color:#fff; }

.secondary { font-size:12px; color:var(--faint); margin:6px 0 0; word-break:break-all; }
.removerow { margin-top:6px; }
.removelink { font-size:12px; color:var(--faint); background:none; border:none; cursor:pointer; padding:0; }
.removelink:hover { color:var(--danger); }
.confirmdel { font-size:12px; color:var(--danger); display:inline-flex; gap:8px; align-items:center; }
.confirmdel button { font-size:12px; border-radius:6px; padding:3px 9px; cursor:pointer; border:1px solid var(--line); background:#fff; }
.confirmdel .yes { background:var(--danger); color:#fff; border-color:var(--danger); }

mark { background:#fff3b0; color:inherit; padding:0 1px; border-radius:2px; }
.empty { text-align:center; color:var(--muted); padding:40px 16px; border:1px dashed var(--line); border-radius:12px; background:var(--card); }
.empty b { color:var(--ink); }

