// Front-end for the bookmark app. Talks to the JSON API and renders the approved
// behaviours. Domain rules (search, tag normalisation, ordering) come from the
// shared logic module so the browser and server agree.

import {
  hostOf,
  allTags,
  visibleLinks,
} from "./logic.js";

const state = {
  links: [],
  view: "all", // "all" | "list"
  q: "",
  tagFilters: [],
};
