      nv.appendChild(highlight(link.note));
      nv.onclick = () => { ui.editingNote[link.id] = true; render(); };
      body.appendChild(nv);
    } else {
      const na = el("button", "miniadd", "＋ Add a note");
      na.onclick = () => { ui.editingNote[link.id] = true; render(); };
