      no.onclick = () => { delete ui.confirmingDelete[link.id]; render(); };
      cd.append(yes, no);
      rr.appendChild(cd);
    } else {
      const rl = el("button", "removelink", "Remove");
      rl.onclick = () => { ui.confirmingDelete[link.id] = true; render(); };
      rr.appendChild(rl);
    }
    body.appendChild(rr);
  }

